-- rls_group_B_candidate_validate.sql — READ-ONLY. متوقّع: enabled=23, policies=23.
SELECT 'groupB_rls_enabled' AS check, count(*) AS n
FROM pg_class WHERE relnamespace='public'::regnamespace AND relkind='r' AND relrowsecurity AND relforcerowsecurity
AND relname IN ('doctor_inventory_requests','doctor_inventory_request_items','hand_hygiene_audits','infection_outbreaks','infection_surveillance','inventory_items','inventory_purchases','inventory_purchase_items','inventory_issue_to_dept','inventory_issue_items','inventory_dept_requests','inventory_dept_request_items','inventory_stock_count','inventory_opening_balances','maintenance_equipment','maintenance_pm_schedules','maintenance_work_orders','pharmacy_purchase_orders','pharmacy_purchase_items','pharmacy_opening_balances','pharmacy_suppliers','quality_kpis','transport_requests');
SELECT 'groupB_policies' AS check, count(*) AS n
FROM pg_policies WHERE policyname LIKE 'rls_%_tenant_isolation' AND tablename IN ('doctor_inventory_requests','doctor_inventory_request_items','hand_hygiene_audits','infection_outbreaks','infection_surveillance','inventory_items','inventory_purchases','inventory_purchase_items','inventory_issue_to_dept','inventory_issue_items','inventory_dept_requests','inventory_dept_request_items','inventory_stock_count','inventory_opening_balances','maintenance_equipment','maintenance_pm_schedules','maintenance_work_orders','pharmacy_purchase_orders','pharmacy_purchase_items','pharmacy_opening_balances','pharmacy_suppliers','quality_kpis','transport_requests');
